{
  "blocks": [
    {
      "id": "b1",
      "kind": "normal",
      "events": [
        { "id": "e1", "type": "action", "actor": "player", "op": "walk_to", "target": "window", "duration": 2.0 },
        { "id": "e2", "type": "speech", "actor": "player", "content": "你听到了吗？", "target": "erin", "duration": 1.5, "parallelWith": ["e1"] }
      ]
    },
    {
      "id": "b2",
      "kind": "wait",
      "responseWindow": true
    }
  ]
}

