    { "type": "action", "op": "glance_around", "duration": 0.6 },
    { "type": "speech", "speechPlan": { "summary": "想向玩家表达的意思", "beats": [{ "meaning": "必须表达的事实", "required": true }], "tone": "克制", "verbosity": "normal", "boundaries": [] }, "target": "player", "duration": 2.0 }
  ]
}

